import sys
from datetime import datetime

def parse_time(time_str):
    h, m = map(int, time_str.split(':'))
    return datetime.combine(datetime.today(), datetime.min) + timedelta(hours=h, minutes=m)


def main():
    bookings = []
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        parts = line.split()
        if parts[0] == "book":
            bid, room, day, start, end = parts[1:]
            start_time = parse_time(start)
            end_time = parse_time(end)
            if end_time <= start_time:
                print("INVALID", bid)
                continue
            conflict = None
            for other_bid, other_room, other_day, other_start, other_end in bookings:
                if other_room == room and other_day == day and not (end_time <= other_start or start_time <= other_end):
                    conflict = other_bid
                    break
            if conflict:
                print("REJECT", bid, conflict)
            else:
                bookings.append((bid, room, day, start_time, end_time))
                print("ACCEPT", bid)
        elif parts[0] == "cancel":
            bookings = [b for b in bookings if b[0] != parts[1]]
            print("CANCELLED", parts[1])
    rooms = {}
    for bid, room, day, start_time, end_time in bookings:
        rooms[room] = rooms.get(room, 0) + 1
    for room in sorted(rooms):
        active_bookings = []
        total_time = timedelta()
        for bid, r, d, s, e in bookings:
            if r == room:
                active_bookings.append((bid, s, e))
        if active_bookings:
            active_bookings.sort(key=lambda x: x[1])
            total_time = timedelta()
            for bid, start, end in active_bookings:
                total_time += end - start
            hours = int(total_time.seconds / 3600)
            minutes = int((total_time.seconds % 3600) // 60)
            print(f"{room} {len(active_bookings)} {hours}:{minutes:02d}")
